    /* landing pages — shared blocks */
    "lp.introt":"Прямая и надёжная доставка",
    "lp.f1t":"Мультимодальные маршруты","lp.f1d":"Авто, ж/д, море и авиа — самый выгодный маршрут для вашего груза.",
